CREATE TABLE platforms(id TEXT PRIMARY KEY, name TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE accounts(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, alias TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX account_platform ON accounts(platform_id);
CREATE TABLE requests(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, current_revision INTEGER NOT NULL DEFAULT 1, rules_json TEXT NOT NULL, auth_paused INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, safe_host TEXT NOT NULL DEFAULT '', method TEXT NOT NULL DEFAULT 'GET');
CREATE INDEX request_account ON requests(account_id);
CREATE TABLE request_revisions(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, revision INTEGER NOT NULL, ciphertext TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(request_id,revision));
CREATE TABLE platform_schedules(platform_id TEXT PRIMARY KEY REFERENCES platforms(id) ON DELETE CASCADE, revision INTEGER NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 0, frequency TEXT NOT NULL DEFAULT 'daily', weekdays_json TEXT NOT NULL DEFAULT '[1,2,3,4,5,6,7]', times_json TEXT NOT NULL DEFAULT '["09:00"]', timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai', interval_seconds INTEGER NOT NULL DEFAULT 2, catchup_minutes INTEGER NOT NULL DEFAULT 0, skip_completed_daily INTEGER NOT NULL DEFAULT 1, effective_from TEXT NOT NULL);
CREATE TABLE run_batches(id TEXT PRIMARY KEY, platform_id TEXT NOT NULL REFERENCES platforms(id) ON DELETE CASCADE, schedule_revision INTEGER NOT NULL, scheduled_at TEXT, business_date TEXT NOT NULL, timezone TEXT NOT NULL, source TEXT NOT NULL, manual_key TEXT UNIQUE, force INTEGER NOT NULL DEFAULT 0, skip_completed_daily INTEGER NOT NULL DEFAULT 1, interval_seconds INTEGER NOT NULL, expires_at TEXT, status TEXT NOT NULL DEFAULT 'queued', cancel_requested INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX occurrence_once ON run_batches(platform_id,scheduled_at) WHERE source='auto';
CREATE TABLE run_items(id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES run_batches(id) ON DELETE CASCADE, request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, request_revision INTEGER NOT NULL, rules_json TEXT NOT NULL, ordinal INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued', http_status INTEGER, duration_ms INTEGER, safe_summary TEXT NOT NULL DEFAULT '', started_at TEXT, finished_at TEXT);
CREATE INDEX items_batch ON run_items(batch_id,ordinal);
CREATE INDEX items_request ON run_items(request_id,status);
CREATE INDEX items_finished ON run_items(finished_at);
CREATE TABLE daily_completions(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, business_date TEXT NOT NULL, completed_run_id TEXT NOT NULL, PRIMARY KEY(request_id,business_date));
CREATE TABLE request_day_states(request_id TEXT NOT NULL REFERENCES requests(id) ON DELETE CASCADE, business_date TEXT NOT NULL, unknown_pending INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(request_id,business_date));
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), paused INTEGER NOT NULL DEFAULT 0, concurrency INTEGER NOT NULL DEFAULT 2, timeout_seconds INTEGER NOT NULL DEFAULT 20, retention_days INTEGER NOT NULL DEFAULT 30, version INTEGER NOT NULL DEFAULT 1);
